const state={filters:new Set(),search:'',sort:'popular',bench:'All',period:'Week',metric:'Tokens',rankTask:'Programming',oriHarness:'claude',oriModel:'openrouter/auto',oriOS:'macOS',providerSearch:'',providerFilters:new Set(),providerCompare:new Set()};

function icon(name){return `<i data-lucide="${name}"></i>`}
function logo(m,small=''){return `<span class="provider-logo ${small}" style="background:${m.color}">${m.logo}</span>`}
function footer(){return `<footer class="footer-note"><div class="container"><span>OpenRouter UI Study · Interaction prototype</span><span>Independent design exercise · Not affiliated with OpenRouter</span></div></footer>`}
function title(title,copy,meta=''){return `<section class="page-title"><div class="container page-title-row"><div><p class="eyebrow">Model intelligence infrastructure</p><h1>${title}</h1><p>${copy}</p></div>${meta}</div></section>`}
function home(){return `<div class="page"><section class="hero"><div class="container hero-inner"><div><p class="eyebrow">One API · Every model</p><h1>The unified interface for <span>every model</span></h1><p class="hero-copy">Access the world’s best AI models through one normalized API. Better prices, better uptime, and the freedom to route every request your way.</p><div class="hero-actions"><button class="primary" data-toast="API 密钥创建流程已打开">Get API key ${icon('arrow-right')}</button><a class="secondary" href="#models">Discover models ${icon('search')}</a></div></div><div class="router-visual" aria-label="请求智能路由示意图"><div class="route-core">ROUTER</div><div class="route-node"><b style="background:#d7f5e7">O</b>OpenAI</div><div class="route-node"><b style="background:#f4dfcf">A</b>Anthropic</div><div class="route-node"><b style="background:#dfeaff">G</b>Google</div><div class="route-node"><b style="background:#dce7ff">D</b>DeepSeek</div><div class="route-lines"><span></span><span></span><span></span><span></span></div></div></div></section><section class="stats-band"><div class="container stats"><div class="stat"><strong>300T+</strong><span>Monthly tokens</span></div><div class="stat"><strong>10M+</strong><span>Global users</span></div><div class="stat"><strong>80+</strong><span>Providers</span></div><div class="stat"><strong>500+</strong><span>Active models</span></div></div></section><section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">Infrastructure that adapts</p><h2>One integration. No compromise.</h2></div><a class="text-link" href="#docs">Read the docs ${icon('arrow-up-right')}</a></div><div class="feature-grid"><article class="feature"><span class="feature-icon">${icon('blocks')}</span><h3>Every modality</h3><p>Text, images, video and audio through a single normalized interface.</p></article><article class="feature"><span class="feature-icon">${icon('route')}</span><h3>Higher availability</h3><p>Automatic fallbacks across providers keep production traffic moving.</p></article><article class="feature"><span class="feature-icon">${icon('gauge')}</span><h3>Price & performance</h3><p>Route for cost, latency, throughput or your own custom priorities.</p></article><article class="feature"><span class="feature-icon">${icon('shield-check')}</span><h3>Data policies</h3><p>Control which providers can process your prompts and responses.</p></article></div></div></section>${footer()}</div>`}

function modelsPage(){return `<div class="page">${title('Models','Browse, compare, and route to 500+ models from the world’s leading AI providers.','<div class="meta-line"><span>500+ MODELS</span><span>80+ PROVIDERS</span></div>')}<div class="container collection-strip"><button data-collection="reasoning"><span class="collection-icon">${icon('brain-circuit')}</span><span><strong>Frontier reasoning</strong><small>Best for hard, multi-step work</small></span>${icon('arrow-right')}</button><button data-collection="multimodal"><span class="collection-icon">${icon('scan-eye')}</span><span><strong>Multimodal</strong><small>Models that see and hear</small></span>${icon('arrow-right')}</button><button data-collection="free"><span class="collection-icon">${icon('badge-dollar-sign')}</span><span><strong>Free models</strong><small>Experiment without usage cost</small></span>${icon('arrow-right')}</button></div><div class="container catalog-layout"><aside class="filter-side" id="filterSide"><div class="filter-title"><span>${icon('list-filter')} Filter models</span><button id="resetFilters">Reset</button></div>${filterGroup('Input modality',['Text','Image','Audio','Video'])}${filterGroup('Capabilities',['Reasoning','Tools'])}${filterGroup('Pricing',['Free'])}</aside><section><div class="model-toolbar"><button class="icon-btn secondary mobile-filter" id="mobileFilter" title="筛选模型">${icon('list-filter')}</button><label class="search">${icon('search')}<input id="modelSearch" value="${state.search}" placeholder="Search by model or provider…"><kbd>/</kbd></label><label class="select-wrap"><select id="modelSort"><option value="popular" ${state.sort==='popular'?'selected':''}>Most popular</option><option value="price" ${state.sort==='price'?'selected':''}>Lowest price</option><option value="context" ${state.sort==='context'?'selected':''}>Largest context</option></select>${icon('chevron-down')}</label></div><div class="result-head"><p class="model-count" id="modelCount"></p><span>PRICING / 1M TOKENS</span></div><div class="model-list" id="modelList"></div></section></div>${footer()}</div>`}
function filterGroup(name,items){return `<div class="filter-group"><h3>${name}</h3>${items.map(x=>`<label class="check"><input type="checkbox" value="${x}" ${state.filters.has(x)?'checked':''}><span>${x}</span></label>`).join('')}</div>`}
function renderModels(){let data=models.filter(m=>(!state.search||`${m.name} ${m.vendor}`.toLowerCase().includes(state.search.toLowerCase()))&&[...state.filters].every(x=>m.tags.includes(x)));if(state.sort==='price')data.sort((a,b)=>a.input-b.input);if(state.sort==='context')data.sort((a,b)=>(parseFloat(b.context)||0)-(parseFloat(a.context)||0));document.querySelector('#modelCount').textContent=`Showing ${data.length} of ${models.length} featured models`;document.querySelector('#modelList').innerHTML=data.length?data.map((m,i)=>`<article class="model-row" data-detail="${m.id}" tabindex="0"><div><div class="model-name">${logo(m)}<div><h3>${m.name}${i<2?'<span class="new-label">NEW</span>':''}</h3><p class="byline">by ${m.vendor} · ${m.tokens} processed</p></div></div><p class="model-desc">${m.desc}</p></div><div class="model-tags">${m.tags.map(x=>`<span class="tag ${x==='Free'?'green':''}">${x}</span>`).join('')}<span class="tag">${m.context}${m.context==='Audio'?' input':' context'}</span></div><div class="price">${m.priceLabel||`$${m.input}/M <span>input tokens</span>$${m.output}/M <span>output tokens</span>`}<b class="row-arrow">${icon('arrow-up-right')}</b></div></article>`).join(''):`<div class="empty">${icon('search-x')}<p>No models match these filters.</p></div>`;lucide.createIcons()}

function providersPage(){return `<div class="page providers-page">${title('Providers','Compare inference providers by privacy policy, data retention, geography, traffic, and available models.','<div class="meta-line"><span>83 PROVIDERS</span><span>GLOBAL ROUTING</span></div>')}<div class="container provider-summary"><div><span>${icon('server')} ACTIVE PROVIDERS</span><strong>83</strong><small>Across 30+ regions</small></div><div><span>${icon('shield-check')} ZERO RETENTION</span><strong>48</strong><small>Policy-compatible endpoints</small></div><div><span>${icon('key-round')} SUPPORTS BYOK</span><strong>64</strong><small>Bring your own provider key</small></div><div><span>${icon('waypoints')} DAILY VOLUME</span><strong>16.2T</strong><small>Tokens routed yesterday</small></div></div><div class="container provider-workspace"><div class="provider-toolbar"><label class="search provider-search">${icon('search')}<input id="providerSearch" value="${state.providerSearch}" placeholder="Search providers…"><kbd>/</kbd></label><div class="provider-filter-tabs">${[['zdr','Zero retention'],['byok','BYOK'],['notrain','No training']].map(([id,n])=>`<button class="${state.providerFilters.has(id)?'active':''}" data-provider-filter="${id}">${n}${state.providerFilters.has(id)?icon('x'):''}</button>`).join('')}</div><button class="secondary compare-button" id="compareProviders" ${state.providerCompare.size<2?'disabled':''}>${icon('columns-3')} Compare <b>${state.providerCompare.size}</b></button></div><div class="provider-result-row"><span id="providerCount"></span><span>${icon('info')} Provider policies can change. Review linked terms before routing sensitive data.</span></div><div class="providers-table" id="providersTable"></div><div class="provider-pagination"><button class="icon-btn secondary" disabled>${icon('chevron-left')}</button><span>Page <strong>1</strong> of 6</span><button class="icon-btn secondary">${icon('chevron-right')}</button></div></div>${footer()}</div>`}
function renderProviders(){const data=providers.filter(p=>(!state.providerSearch||p.name.toLowerCase().includes(state.providerSearch.toLowerCase()))&&(!state.providerFilters.has('zdr')||p.retention==='Zero retention')&&(!state.providerFilters.has('byok')||p.byok)&&(!state.providerFilters.has('notrain')||!p.trains));document.querySelector('#providerCount').textContent=`${data.length} shown · 83 providers total`;document.querySelector('#providersTable').innerHTML=`<div class="providers-tr providers-head"><span></span><span>Provider</span><span>Trains</span><span>Retention</span><span>BYOK</span><span>Headquarters</span><span>Policies</span><span>Daily tokens</span><span>Monthly</span><span>Models</span></div>${data.map(p=>`<div class="providers-tr"><label class="compare-check" title="加入对比"><input type="checkbox" data-provider-select="${p.name}" ${state.providerCompare.has(p.name)?'checked':''}><i></i></label><span class="provider-title"><b style="background:${p.color}">${p.mark}</b><strong>${p.name}</strong></span><span class="policy-value ${p.trains?'warning':'good'}">${p.trains?icon('alert-triangle'):icon('check')} ${p.trains?'Yes':'No'}</span><span><em class="retention ${p.retention==='Zero retention'?'zero':''}">${p.retention}</em></span><span class="policy-value ${p.byok?'good':''}">${p.byok?icon('check'):icon('minus')} ${p.byok?'Yes':'No'}</span><span>${p.hq}</span><span class="policy-links"><button title="服务条款">ToS ${icon('arrow-up-right')}</button><button title="隐私政策">Privacy ${icon('arrow-up-right')}</button></span><strong class="provider-volume">${p.daily}</strong><span>${p.monthly}</span><button class="model-total" data-toast="${p.name} 的模型列表已打开">${p.models} ${icon('chevron-right')}</button></div>`).join('')}`;document.querySelectorAll('[data-provider-select]').forEach(x=>x.onchange=e=>{e.target.checked?state.providerCompare.add(e.target.dataset.providerSelect):state.providerCompare.delete(e.target.dataset.providerSelect);renderProviders();syncProviderCompare()});lucide.createIcons()}
function syncProviderCompare(){const b=document.querySelector('#compareProviders');b.disabled=state.providerCompare.size<2;b.querySelector('b').textContent=state.providerCompare.size}
function openProviderCompare(){const selected=providers.filter(p=>state.providerCompare.has(p.name));document.querySelector('#modelDrawer').innerHTML=`<button class="icon-btn drawer-close" data-close-drawer>${icon('x')}</button><div class="provider-compare-title"><p class="eyebrow">Side by side</p><h2>Compare providers</h2><p>Policy and usage signals for your selected providers.</p></div><div class="provider-compare-grid">${selected.map(p=>`<article><span class="provider-title"><b style="background:${p.color}">${p.mark}</b><strong>${p.name}</strong></span><dl><dt>Training</dt><dd>${p.trains?'Allowed':'No'}</dd><dt>Retention</dt><dd>${p.retention}</dd><dt>BYOK</dt><dd>${p.byok?'Yes':'No'}</dd><dt>Headquarters</dt><dd>${p.hq}</dd><dt>Daily tokens</dt><dd>${p.daily}</dd><dt>Models</dt><dd>${p.models}</dd></dl></article>`).join('')}</div><button class="primary provider-compare-cta" data-toast="Provider 路由策略已创建">Create routing policy ${icon('arrow-right')}</button>`;const shell=document.querySelector('#drawerShell');shell.classList.add('open');shell.setAttribute('aria-hidden','false');lucide.createIcons()}

function detailCode(m){return `<span class="fn">curl</span> https://openrouter.ai/api/v1/${m.id==='mai-transcribe-2'?'audio/transcriptions':'chat/completions'} \\
  -H <span class="str">"Authorization: Bearer $OPENROUTER_API_KEY"</span> \\
  ${m.id==='mai-transcribe-2'?`-F <span class="str">"file=@meeting.mp3"</span> \\
  -F <span class="str">"model=microsoft/${m.id}"</span>`:`-H <span class="str">"Content-Type: application/json"</span> \\
  -d <span class="str">'{"model":"${m.vendor.toLowerCase()}/${m.id}","messages":[{"role":"user","content":"Hello"}]}'</span>`}`}
function modelDetailPage(m,active='overview'){const audio=m.id==='mai-transcribe-2',price=m.priceLabel||`$${m.input}/M input · $${m.output}/M output`;return `<div class="page model-detail"><div class="detail-breadcrumb container"><a href="#models">Models</a>${icon('chevron-right')}<span>${m.vendor}</span>${icon('chevron-right')}<strong>${m.name}</strong></div><section class="detail-hero"><div class="container detail-hero-inner"><div><div class="detail-identity">${logo(m)}<div><p>${m.vendor.toUpperCase()} / ${m.id}</p><h1>${m.vendor}: ${m.name}</h1></div></div><p class="detail-summary">${m.desc}${audio?' It is suited for captions, call transcription, subtitling, accessibility, and other voice-enabled applications.':''}</p><div class="model-tags">${m.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div></div><div class="detail-actions"><button class="secondary copy-id" data-copy="${m.vendor.toLowerCase()}/${m.id}">${icon('copy')} Copy model ID</button><button class="primary" data-toast="模型 Playground 已打开">${audio?icon('mic-2'):icon('message-square')} Try model</button></div></div></section><nav class="detail-nav"><div class="container">${['overview','providers','activity','apps'].map(x=>`<a class="${active===x?'active':''}" href="#model/${m.id}/${x}">${x[0].toUpperCase()+x.slice(1)}</a>`).join('')}</div></nav><div class="container detail-body"><main id="overview"><section class="detail-metrics"><div><span>MODALITIES</span><strong>${audio?`${icon('audio-lines')} Audio ${icon('arrow-right')} Text`:`${icon('message-square')} Text ${icon('arrow-right')} Text`}</strong></div><div><span>PRICE</span><strong>${price}</strong></div><div><span>RELEASED</span><strong>${m.released||'Aug 2026'}</strong></div><div><span>CONTEXT</span><strong>${audio?'60 languages':m.context+' tokens'}</strong></div></section><section class="detail-section" id="providers"><div class="detail-section-head"><div><p class="eyebrow">Routing</p><h2>Providers for ${m.name}</h2></div><button class="icon-btn secondary" title="刷新 Provider">${icon('refresh-cw')}</button></div><p>OpenRouter routes requests to the best available provider that matches your preferences.</p><div class="provider-table"><div class="provider-tr table-head"><span>Provider</span><span>${audio?'Audio / hr':'Input / M'}</span><span>Latency</span><span>Uptime</span></div><div class="provider-tr"><span class="provider-cell"><b style="background:#dcecff">${m.vendor[0]}</b>${audio?'Azure':m.vendor}<small>US East · EU West</small></span><strong>${audio?'$0.10':`$${m.input}`}</strong><strong>${m.latency||'0.62 s'}</strong><strong class="healthy">${m.uptime||'99.99%'}</strong></div></div></section><section class="detail-section" id="activity"><div class="detail-section-head"><div><p class="eyebrow">Reliability</p><h2>Availability over the last 3 days</h2></div><span class="live-label"><i></i> Live</span></div><div class="availability-card"><div class="availability-top"><div><span>OPENROUTER AVAILABILITY</span><strong>99.95%</strong></div><div><span>BEST PROVIDER UPTIME</span><strong>${m.uptime||'99.99%'}</strong></div><div><span>P50 LATENCY</span><strong>${m.latency||'0.62 s'}</strong></div></div><div class="uptime-grid">${Array.from({length:72},(_,i)=>`<i class="${i===38?'warn':''}" title="${i} hours ago"></i>`).join('')}</div><div class="uptime-axis"><span>3 days ago</span><span>2 days ago</span><span>Yesterday</span><span>Now</span></div></div></section><section class="detail-section"><p class="eyebrow">Integration</p><h2>Use this model</h2><p>Send requests with the model identifier below. Provider routing and fallbacks happen automatically.</p><div class="code-box"><div class="code-head"><span>cURL</span><button class="copy-btn detail-code-copy" aria-label="复制代码">${icon('copy')}</button></div><pre><code id="detailCode">${detailCode(m)}</code></pre></div></section><section class="detail-section faq-section"><p class="eyebrow">FAQ</p><h2>Frequently asked questions</h2>${faqItem(`What is ${m.name}?`,m.desc,true)}${faqItem(`How much does ${m.name} cost?`,`${m.name} costs ${price}.`)}${faqItem(`What inputs and outputs are supported?`,audio?'It accepts audio input and returns timestamped transcribed text.':'It accepts text and multimodal input and returns generated text.')} ${faqItem(`When was ${m.name} released?`,`${m.name} was released ${m.released||'in 2026'}.`)}</section></main><aside class="detail-aside"><div class="aside-card"><span>MODEL ID</span><code>${m.vendor.toLowerCase()}/${m.id}</code><button class="secondary copy-id" data-copy="${m.vendor.toLowerCase()}/${m.id}">${icon('copy')} Copy</button></div><div class="aside-card" id="apps"><span>TOP APPS THIS WEEK</span>${['Chataigne Analytics','Exati Chat','maia-bench','Dictate'].map((x,i)=>`<div class="app-rank"><b>${i+1}</b><i>${x[0]}</i><span>${x}<small>${i?'—':'New'}</small></span></div>`).join('')}</div><div class="aside-card policy"><span>DATA POLICY</span>${icon('shield-check')}<strong>Provider policy compatible</strong><p>No training on prompts unless explicitly allowed.</p></div></aside></div>${footer()}</div>`}
function faqItem(q,a,open=false){return `<div class="faq-item ${open?'open':''}"><button aria-expanded="${open}"><span>${q}</span>${icon('plus')}</button><div><p>${a}</p></div></div>`}

const detailNavItems=[['providers','server-cog'],['pricing','badge-dollar-sign'],['performance','gauge'],['uptime','activity'],['benchmarks','bar-chart-3'],['apps','blocks'],['activity','chart-no-axes-combined'],['faq','circle-help'],['explore','compass']];
function detailProviderRows(m){const gemini=m.id==='gemini-3.8-flash';const rows=gemini?[['Google AI Studio Flex','$0.375','$1.875','2.01s','92 tps','98.98%'],['Google Vertex Flex','$0.375','$1.875','12.62s','32 tps','97.05%'],['Google AI Studio','$0.75','$3.75','2.46s','84 tps','99.83%'],['Google Vertex','$0.75','$3.75','2.33s','73 tps','99.38%'],['Google AI Studio Priority','$1.35','$6.75','2.70s','208 tps','99.32%'],['Google Vertex Priority','$1.35','$6.75','2.83s','98 tps','99.85%']]:[[m.id==='mai-transcribe-2'?'Azure':m.vendor,m.priceLabel||`$${m.input}`,m.id==='mai-transcribe-2'?'—':`$${m.output}`,m.latency||'0.62s',m.throughput||'84 tps',m.uptime||'99.99%']];return rows.map((r,i)=>`<div class="provider-data-row"><span><b style="background:${i%2?'#e8eef9':m.color}">${r[0][0]}</b><span><strong>${r[0]}</strong><small>${i<2?'Flex tier':'Standard tier'}${i>3?' · Priority':''}</small></span></span><code>${r[1]}</code><code>${r[2]}</code><code>${r[3]}</code><code>${r[4]}</code><code class="healthy">${r[5]}</code></div>`).join('')}
function metricBars(values,labels,unit){return `<div class="metric-bars">${values.map((v,i)=>`<div><span>${labels[i]}</span><i><b style="width:${v}%"></b></i><strong>${unit==='%'?v+'%':Math.round(v*2.08)+' '+unit}</strong></div>`).join('')}</div>`}
function modelDetailPageV2(m,active='providers'){const audio=m.id==='mai-transcribe-2',price=m.priceLabel||`$${m.input}/M input · $${m.output}/M output`,apps=['Hermes Agent','Pi','OpenClaw','Kilo Code','OpenCode'],related=models.filter(x=>x.id!==m.id).slice(0,3);return `<div class="page model-detail"><div class="detail-breadcrumb container"><a href="#models">Models</a>${icon('chevron-right')}<span>${m.vendor}</span>${icon('chevron-right')}<strong>${m.name}</strong></div><section class="detail-hero"><div class="container detail-hero-inner"><div><div class="detail-identity">${logo(m)}<div><p>${m.vendor.toUpperCase()} / ${m.id}</p><h1>${m.vendor}: ${m.name}</h1></div></div><p class="detail-summary">${m.desc}${audio?' It is suited for captions, call transcription, subtitling, accessibility, and voice-enabled applications.':''}</p><div class="model-tags">${m.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div></div><div class="detail-actions"><button class="secondary copy-id" data-copy="${m.vendor.toLowerCase()}/${m.id}">${icon('copy')} Copy model ID</button><button class="primary" data-toast="模型 Playground 已打开">${audio?icon('mic-2'):icon('message-square')} Try model</button></div></div></section><div class="container detail-shell"><aside class="model-section-nav"><div class="model-nav-meta"><span>MODEL DETAILS</span><strong>${m.name}</strong></div><nav>${detailNavItems.map(([id,ic])=>`<a class="${active===id?'active':''}" href="#model/${m.id}/${id}">${icon(ic)}<span>${id[0].toUpperCase()+id.slice(1)}</span>${icon('chevron-right')}</a>`).join('')}</nav><div class="model-nav-footer"><span>${icon('radio')} Live data</span><small>Updated just now</small></div></aside><main class="model-section-content"><section class="detail-metrics compact"><div><span>MODALITIES</span><strong>${audio?`${icon('audio-lines')} Audio ${icon('arrow-right')} Text`:`${icon('scan-eye')} Multimodal ${icon('arrow-right')} Text`}</strong></div><div><span>IN / OUT PRICE</span><strong>${price}</strong></div><div><span>CONTEXT</span><strong>${audio?'60 languages':m.context+' tokens'}</strong></div><div><span>RELEASED</span><strong>${m.released||'Aug 2026'}</strong></div></section><section class="model-section" id="providers"><div class="model-section-head"><div><p class="eyebrow">Providers</p><h2>Provider routing</h2><p>OpenRouter routes to the best endpoint that matches your preferences, with automatic failover.</p></div><div class="section-controls"><button class="secondary">Standard ${icon('chevron-down')}</button><button class="icon-btn secondary" data-toast="Provider 数据已刷新">${icon('refresh-cw')}</button></div></div><div class="provider-data-table"><div class="provider-data-row header"><span>Provider</span><span>Input /M</span><span>Output /M</span><span>Latency</span><span>Throughput</span><span>Uptime</span></div>${detailProviderRows(m)}</div></section><section class="model-section" id="pricing"><div class="model-section-head"><div><p class="eyebrow">Pricing</p><h2>Transparent, usage-based pricing</h2><p>Pay only for usage. OpenRouter does not add a subscription to model pricing.</p></div><span class="tag green">${m.id==='gemini-3.8-flash'?'50% OFF':'LIVE RATE'}</span></div><div class="pricing-grid"><div><span>INPUT TOKENS</span><strong>${audio?'$0.10/hr':`$${m.input}`}</strong><small>${audio?'per audio hour':'per 1M tokens'}</small></div><div><span>OUTPUT TOKENS</span><strong>${audio?'Included':`$${m.output}`}</strong><small>${audio?'transcribed text':'per 1M tokens'}</small></div><div><span>CACHE READ</span><strong>${audio?'—':`$${(m.input/10).toFixed(3)}`}</strong><small>per 1M tokens</small></div><div><span>WEB SEARCH</span><strong>${audio?'—':'$14.00'}</strong><small>per 1K calls</small></div></div><div class="cost-calculator"><div><span>${icon('calculator')} Cost calculator</span><strong id="tokenAmount">10M tokens</strong></div><input id="costRange" type="range" min="1" max="100" value="10"><p>Estimated input cost <strong id="costEstimate">$${(m.input*10).toFixed(2)}</strong></p></div></section><section class="model-section" id="performance"><div class="model-section-head"><div><p class="eyebrow">Performance</p><h2>Latency and throughput</h2><p>P50 measurements across active providers over the selected period.</p></div><div class="tabs mini"><button class="active">3 days</button><button>7 days</button><button>30 days</button></div></div><div class="performance-grid"><div class="performance-card"><span>THROUGHPUT</span><strong>${m.throughput||'208 tok/s'}</strong><small>P50, best provider</small>${metricBars([44,58,54,71,68,81,76,92],['12a','4a','8a','12p','4p','8p','12a','Now'],'tps')}</div><div class="performance-card"><span>LATENCY</span><strong>${m.latency||'2.01 s'}</strong><small>P50, best provider</small>${metricBars([82,64,71,49,56,44,51,38],['12a','4a','8a','12p','4p','8p','12a','Now'],'%')}</div></div></section><section class="model-section" id="uptime"><div class="model-section-head"><div><p class="eyebrow">Uptime</p><h2>Availability over the last 3 days</h2></div><span class="live-label"><i></i> Live</span></div><div class="availability-card"><div class="availability-top"><div><span>OPENROUTER AVAILABILITY</span><strong>${m.id==='gemini-3.8-flash'?'99.71%':'99.95%'}</strong></div><div><span>WITHOUT ROUTING</span><strong>${m.id==='gemini-3.8-flash'?'96.58%':m.uptime||'99.99%'}</strong></div><div><span>BEST PROVIDER UPTIME</span><strong>${m.uptime||'100.00%'}</strong></div></div><div class="uptime-grid">${Array.from({length:72},(_,i)=>`<i class="${[22,38,39].includes(i)?'warn':''}"></i>`).join('')}</div><div class="uptime-axis"><span>3 days ago</span><span>2 days ago</span><span>Yesterday</span><span>Now</span></div></div></section><section class="model-section" id="benchmarks"><div class="model-section-head"><div><p class="eyebrow">Benchmarks</p><h2>Capability benchmarks</h2><p>Independent measurements across reasoning, programming, and multimodal tasks.</p></div><a class="text-link" href="#benchmarks">Compare all ${icon('arrow-up-right')}</a></div><div class="benchmark-rows">${[['Programming',76,24],['Science',83,11],['Long context',91,6],['Multimodal',88,8],['Reasoning',72,29]].map(([n,v,r])=>`<div><span>${n}</span><i><b style="width:${v}%"></b></i><strong>${v}.0</strong><small>#${r}</small></div>`).join('')}</div></section><section class="model-section" id="apps"><div class="model-section-head"><div><p class="eyebrow">Apps</p><h2>Apps using ${m.name}</h2><p>Popular public applications ranked by tokens processed this week.</p></div></div><div class="detail-app-list">${apps.map((x,i)=>`<article><b>${String(i+1).padStart(2,'0')}</b><i>${x[0]}</i><span><strong>${x}</strong><small>${['Open-source agent with memory and 40+ tools','The coding agent that is yours','Personal AI assistant','Agentic coding for IDE and CLI','Open source coding agent'][i]}</small></span><em>${['52.5B','25.8B','7.45B','6.41B','4.92B'][i]}<small>tokens</small></em></article>`).join('')}</div></section><section class="model-section" id="activity"><div class="model-section-head"><div><p class="eyebrow">Activity</p><h2>Usage activity</h2><p>Token volume routed through OpenRouter over the last 14 days.</p></div><span class="tag">UTC</span></div><div class="activity-chart">${[35,49,44,58,61,72,68,79,83,76,91,87,96,100].map((v,i)=>`<i style="height:${v}%"><span>${Math.round(v*4.79)}B</span><small>${i+21}</small></i>`).join('')}</div></section><section class="model-section faq-section" id="faq"><p class="eyebrow">FAQ</p><h2>Frequently asked questions</h2>${faqItem(`What is ${m.name}?`,m.desc,true)}${faqItem(`How much does ${m.name} cost?`,`${m.name} costs ${price}.`)}${faqItem(`What inputs and outputs are supported?`,audio?'It accepts audio and returns timestamped text.':'It accepts text, images, video, PDFs, and audio, and returns text.')} ${faqItem(`Which providers serve ${m.name}?`,m.id==='gemini-3.8-flash'?'Google AI Studio and Google Vertex serve this model across Flex, Standard, and Priority tiers.':`${m.vendor} provides active endpoints for this model.`)}</section><section class="model-section" id="explore"><div class="model-section-head"><div><p class="eyebrow">Explore</p><h2>Related models</h2><p>Compare similar models by price, context, and capabilities.</p></div><a class="text-link" href="#models">Browse all ${icon('arrow-right')}</a></div><div class="related-models">${related.map(x=>`<button data-detail="${x.id}">${logo(x)}<span><strong>${x.name}</strong><small>${x.vendor} · ${x.context} context</small></span><em>$${x.input}/M</em>${icon('arrow-up-right')}</button>`).join('')}</div></section></main><aside class="detail-aside"><div class="aside-card"><span>MODEL ID</span><code>${m.vendor.toLowerCase()}/${m.id}</code><button class="secondary copy-id" data-copy="${m.vendor.toLowerCase()}/${m.id}">${icon('copy')} Copy</button></div><div class="aside-card quickstart"><span>QUICKSTART</span><p>Use this model with one normalized API request.</p><div class="mini-code"><code>model: '${m.vendor.toLowerCase()}/${m.id}'</code></div><button class="primary" data-toast="API 示例已打开">View API example ${icon('arrow-right')}</button></div><div class="aside-card policy"><span>DATA POLICY</span>${icon('shield-check')}<strong>Provider policy compatible</strong><p>No training on prompts unless explicitly allowed.</p></div></aside></div>${footer()}</div>`}

function benchmarkPage(){return `<div class="page">${title('Benchmarks','Independent, reproducible measurements of model quality, value, and speed. Every score links back to the exact configuration.','<div class="meta-line"><span>6 BENCHMARKS</span><span>2.45M EVALUATIONS</span></div>')}<div class="container"><div class="benchmark-tools"><div class="tabs" id="benchTabs">${['All','Agents','Reasoning','Search'].map(x=>`<button class="${state.bench===x?'active':''}" data-bench="${x}">${x}</button>`).join('')}</div><a class="text-link" data-toast="API 参考已打开">Benchmarks API ${icon('arrow-up-right')}</a></div><div class="benchmark-grid" id="benchmarkGrid"></div></div>${footer()}</div>`}
function renderBenchmarks(){document.querySelector('#benchmarkGrid').innerHTML=benchmarks.filter(b=>state.bench==='All'||b.cat===state.bench).map(b=>`<article class="benchmark-card" data-toast="${b.name} 的完整配置已打开"><div class="bench-top"><div><span class="tag">${b.cat}</span><h3>${b.name}</h3><p>${b.desc}</p></div><span class="bench-meta">${b.models} MODELS<br>RUN ${b.date}</span></div><div class="scores"><div class="score"><span>QUALITY</span><strong>${b.quality}</strong><small>${b.winner}</small></div><div class="score"><span>VALUE</span><strong>${b.value}</strong><small>per task</small></div><div class="score"><span>SPEED</span><strong>${b.speed}</strong><small>median</small></div></div></article>`).join('');}

function rankingsPage(){return `<div class="page">${title('AI Model Rankings','Live rankings based on real-world usage across millions of developers. Usage data through Sep 3, 2026.','<div class="meta-line"><span>UPDATED DAILY</span><span>CC BY 4.0</span></div>')}<div class="container"><div class="benchmark-tools"><div class="tabs" id="periodTabs">${['Day','Week','Month','Trending'].map(x=>`<button class="${state.period===x?'active':''}" data-period="${x}">${x}</button>`).join('')}</div><div class="tabs" id="metricTabs">${['Tokens','Share'].map(x=>`<button class="${state.metric===x?'active':''}" data-metric="${x}">${x}</button>`).join('')}</div></div><div class="ranking-layout"><section class="chart-panel"><div class="panel-head"><h2>Token volume · last 14 days</h2><span class="tag">UTC</span></div><div class="chart-wrap" id="chart"></div><div class="chart-legend"><span><i class="dot"></i>Top 10 models</span><span><i class="dot" style="background:var(--line)"></i>All others</span></div></section><aside class="leaderboard"><div class="panel-head"><h2>Top models</h2><span class="tag">${state.period}</span></div><ol class="leader-list">${leaders.map((m,i)=>`<li class="leader" data-model="${m.id}"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="leader-model">${logo(m)}<span><strong>${m.name}</strong><small>${m.vendor}</small></span></span><span class="tokens">${m.tokens}<small class="change">+${[586,137,10,59,907,31,22,18][i]}%</small></span></li>`).join('')}</ol></aside></div></div>${footer()}</div>`}
function renderChart(){const sets={Day:[48,62,55,74,82,70,91,77,88,95,81,100,92,106],Week:[38,44,51,49,61,68,64,78,73,88,94,90,105,112],Month:[72,68,75,81,79,86,92,88,97,101,104,110,116,120],Trending:[30,38,35,49,44,58,69,62,81,76,98,91,115,124]};const d=sets[state.period];document.querySelector('#chart').innerHTML=d.map((v,i)=>`<div class="chart-bar" style="height:${v/1.35}%" data-day="${i+21}"><span class="tip">${state.metric==='Share'?(v/2).toFixed(1)+'%':v+'T tokens'}</span></div>`).join('')}

const rankingNavItems=[['top-models','trophy','Top Models'],['leaderboard','list-ordered','Leaderboard'],['tasks','scan-search','Top models by task'],['cost','circle-dollar-sign','Cost per session'],['market','pie-chart','Market Share'],['benchmarks','chart-scatter','Benchmarks'],['fastest','gauge','Fastest models'],['languages','languages','Languages'],['programming','code-2','Programming'],['context','text-select','Context Length'],['tool-calls','wrench','Tool Calls'],['images','image','Images'],['top-apps','blocks','Top Apps']];
function rankingSection(id,title,copy,body,side=''){return `<section class="ranking-section" id="${id}"><div class="ranking-section-head"><div><p class="eyebrow">${id.replaceAll('-',' ')}</p><h2>${title}</h2><p>${copy}</p></div>${side}</div>${body}</section>`}
function rankVendor(name){if(/Claude/i.test(name))return'anthropic';if(/Gemini|Gemma|Banana/i.test(name))return'google';if(/GLM/i.test(name))return'z-ai';if(/DeepSeek/i.test(name))return'deepseek';if(/Kimi/i.test(name))return'moonshotai';if(/Hy4/i.test(name))return'tencent';if(/MiniMax/i.test(name))return'minimax';return'openai'}
function miniRankRows(items,unit='tokens'){return `<div class="mini-rank-list">${items.map((x,i)=>`<div><b>${String(i+1).padStart(2,'0')}</b><i style="background:${x[2]||['#d7f5e7','#f4dfcf','#dfeaff','#e7ddff','#ffe5d3'][i%5]}">${x[0][0]}</i><span><strong>${x[0]}</strong><small>${x[3]||'by '+rankVendor(x[0])}</small></span><em>${x[1]}<small>${unit}</small></em></div>`).join('')}</div>`}
function rankingsPageV2(active='top-models'){const tasks=['Classification','Content Writing','Q&A & Knowledge','Research & Reports','Customer Support','Summarization','Security Audit','Math','Finance & Trading','Translation','DevOps','Code Generation','Debugging','Frontend & UI'];const fast=[['gpt-oss-120b','761 tok/s','#d7f5e7','Cerebras · $0.35/M'],['Nano Banana 2 Lite','467 tok/s','#dfeaff','Google AI Studio · $0.25/M'],['Gemma 4 31B','403 tok/s','#dfeaff','Cerebras · $0.99/M'],['gpt-oss-20b','392 tok/s','#d7f5e7','Groq · $0.07/M'],['Gemini 3.5 Flash Lite','271 tok/s','#dfeaff','Google · $0.33/M']];return `<div class="page rankings-page">${title('AI Model Rankings','Live rankings from real-world usage across millions of developers. Adoption, performance, cost, capabilities, and apps in one view.','<div class="meta-line"><span>UPDATED DAILY</span><span>CC BY 4.0</span></div>')}<div class="container rankings-shell"><aside class="rankings-nav"><div class="ranking-nav-meta"><span>EXPLORE RANKINGS</span><small>Usage through Sep 3, 2026</small></div><nav>${rankingNavItems.map(([id,ic,n])=>`<a class="${active===id?'active':''}" href="#rankings/${id}">${icon(ic)}<span>${n}</span>${icon('chevron-right')}</a>`).join('')}</nav></aside><main class="rankings-content"><div class="rankings-global-tools"><div class="tabs" id="periodTabs">${['Day','Week','Month','Trending'].map(x=>`<button class="${state.period===x?'active':''}" data-period="${x}">${x}</button>`).join('')}</div><div class="rankings-fresh">${icon('radio')} Live dataset · UTC</div></div>${rankingSection('top-models','Top models','Token volume processed through OpenRouter over the selected period.',`<div class="top-model-layout"><div class="ranking-chart-card"><div class="chart-wrap" id="chart"></div><div class="chart-legend"><span><i class="dot"></i>Top 10 models</span><span><i class="dot" style="background:var(--line)"></i>Others</span></div></div>${miniRankRows([['GLM 5.3 Flash','11.9T'],['GPT-5.6 Luna','11.6T'],['DeepSeek V4 Flash','11.3T'],['Hy4 preview','11.0T'],['MiniMax M3','5.15T']])}</div>`,`<div class="tabs" id="metricTabs">${['Tokens','Share'].map(x=>`<button class="${state.metric===x?'active':''}" data-metric="${x}">${x}</button>`).join('')}</div>`)}${rankingSection('leaderboard','Leaderboard','Models ranked by tokens processed, with week-over-week movement.',`<div class="full-leaderboard"><div class="full-leader-head"><span>Rank</span><span>Model</span><span>Share</span><span>Tokens processed</span><span>7d change</span></div>${leaders.map((m,i)=>`<div><b>${i+1}</b><span class="leader-model">${logo(m)}<span><strong>${m.name}</strong><small>${m.vendor}</small></span></span><span>${[12.8,12.4,12.1,8.9,7.2,6.8,5.7,4.9][i]}%</span><strong>${m.tokens}</strong><em>+${[586,137,10,59,907,31,22,18][i]}%</em></div>`).join('')}</div>`,`<button class="secondary export-rank" data-toast="排行榜 CSV 已导出">${icon('download')} Export</button>`)}${rankingSection('tasks','Top models by task','Each task’s leading model, ranked by share of spend on OpenRouter.',`<div class="task-picker">${tasks.map(x=>`<button class="${state.rankTask===x?'active':''}" data-rank-task="${x}"><i>${x.split(' ').map(w=>w[0]).join('').slice(0,2)}</i><span>${x}</span><strong>${['Claude Opus 5','GPT-5.6 Sol','Gemini 3.8 Flash'][tasks.indexOf(x)%3]}</strong>${icon('chevron-right')}</button>`).join('')}</div><div class="task-detail"><div><span>SELECTED TASK</span><h3 id="taskTitle">${state.rankTask}</h3><p>10.1% of all categorized spend</p></div>${miniRankRows([['Claude Opus 5','8.8%'],['GPT-5.6 Sol','6.9%'],['Gemini 3.8 Flash','6.1%'],['Claude Fable 5','4.5%'],['Kimi K3','3.3%']],'share')}</div>`)}${rankingSection('cost','Cost per session','Typical paid usage for one coding-agent session, grouped by session length.',`<div class="cost-controls"><div class="tabs"><button class="active">Hermes Agent</button><button>Claude Code</button><button>Kilo Code</button><button>Codex</button></div><span>Lowest → Highest cost</span></div><div class="cost-table"><div class="cost-tr header"><span>Model</span><span>1 turn</span><span>2–9 turns</span><span>10–49 turns</span><span>50+ turns</span></div>${[['Ling 2.6 Flash','$0.0001','$0.0006','$0.0029','—'],['Ling 3.0 Flash','$0.0004','$0.0013','$0.0097','$0.056'],['GPT-5 Nano','$0.0010','$0.0028','$0.016','—'],['MiMo-V2.5','$0.0018','$0.0043','$0.018','$0.096'],['DeepSeek V4 Flash','$0.0015','$0.0049','$0.033','$0.25']].map((r,i)=>`<div class="cost-tr"><span><b>${i+1}</b>${r[0]}</span>${r.slice(1).map((x,j)=>`<span><i style="width:${Math.max(5,(j+1)*(i+2)*4)}%"></i><strong>${x}</strong></span>`).join('')}</div>`).join('')}</div>`)}${rankingSection('market','Market Share','Share of routed token volume by model author.',`<div class="market-layout"><div class="donut"><strong>100%</strong><span>token volume</span></div><div class="market-list">${[['Google',27,'#7ca7ff'],['OpenAI',23,'#58c792'],['Anthropic',18,'#e6a978'],['DeepSeek',14,'#798fe8'],['Z.ai',9,'#a98bed'],['Others',9,'#bfc0ba']].map(x=>`<div><span><i style="background:${x[2]}"></i>${x[0]}</span><b><i style="width:${x[1]}%;background:${x[2]}"></i></b><strong>${x[1]}%</strong></div>`).join('')}</div></div>`,`<div class="tabs"><button class="active">Percentage</button><button>Absolute</button></div>`)}${rankingSection('benchmarks','Benchmarks','Top models on OpenRouter by Artificial Analysis Intelligence Index.',`<div class="benchmark-rank-layout"><div class="scatter-plot">${[[18,70,'Claude Opus 5'],[31,66,'GPT-5.6 Sol'],[45,59,'Kimi K3'],[57,55,'GLM 5.3'],[72,48,'Gemini 3.8']].map((x,i)=>`<i style="left:${x[0]}%;bottom:${x[1]}%;background:${['#f4dfcf','#d7f5e7','#e7ddff','#d9efff','#dfeaff'][i]}" title="${x[2]}">${i+1}</i>`).join('')}<span class="axis-y">Intelligence ↑</span><span class="axis-x">Input price →</span></div>${miniRankRows([['Claude Opus 5','63.1'],['Claude Fable 5','62.1'],['Grok 4.6','60.9'],['GPT-5.6 Sol','60.9'],['Kimi K3','59.7']],'index')}</div>`,`<label class="pareto"><input type="checkbox"> Show Pareto</label>`)}${rankingSection('fastest','Fastest models','Highest observed output throughput across eligible providers.',miniRankRows(fast,'throughput'),'<span class="tag green">P50 THROUGHPUT</span>')}${rankingSection('languages','Languages','Most-used models across multilingual traffic.',`<div class="language-grid">${[['English','62.4%','GPT-5.6 Sol'],['Chinese','15.8%','DeepSeek V4'],['Spanish','5.7%','Gemini 3.8 Flash'],['Japanese','4.9%','Claude Opus 5'],['Portuguese','3.8%','Gemini 3.8 Flash'],['German','3.1%','Claude Fable 5']].map((x,i)=>`<article><i>${x[0].slice(0,2).toUpperCase()}</i><span><strong>${x[0]}</strong><small>Top: ${x[2]}</small></span><em>${x[1]}</em></article>`).join('')}</div>`)}${rankingSection('programming','Programming','Models ranked specifically by code generation and software-engineering usage.',`<div class="programming-layout">${miniRankRows([['Claude Opus 5','28.7%'],['GPT-5.6 Sol','24.9%'],['DeepSeek V4 Flash','15.2%'],['Qwen3.8 Flash','9.6%'],['Gemini 3.8 Flash','8.4%']],'code share')}<div class="code-share-visual"><span>SHARE OF PROGRAMMING TOKENS</span>${[88,78,62,48,39].map((v,i)=>`<i style="width:${v}%"><b>${i+1}</b></i>`).join('')}</div></div>`)}${rankingSection('context','Context Length','Models with the largest supported prompt windows.',`<div class="context-scale"><div class="context-axis"><span>0</span><span>500K</span><span>1M</span><span>2M</span></div>${[['Gemini 3.8 Flash',52,'1.05M'],['Claude Opus 5',50,'1M'],['Qwen3.8 Flash',50,'1M'],['GLM 5.3 Flash',66,'1.31M'],['MiniMax M3',10,'200K']].map((x,i)=>`<div><span>${x[0]}</span><i><b style="width:${x[1]}%;background:${['#dfeaff','#f4dfcf','#eadfff','#e7ddff','#ddf5f0'][i]}"></b></i><strong>${x[2]}</strong></div>`).join('')}</div>`)}${rankingSection('tool-calls','Tool Calls','Models ranked by tool-call tokens processed through participating apps.',`<div class="tool-call-layout"><div class="big-number"><span>LAST 7 DAYS</span><strong>18.4T</strong><small>tool-call tokens · +24.8%</small></div>${miniRankRows([['Claude Opus 5','4.8T'],['GPT-5.6 Sol','4.1T'],['DeepSeek V4 Flash','2.9T'],['Gemini 3.8 Flash','2.1T'],['Qwen3.8 Flash','1.7T']])}</div>`)}${rankingSection('images','Images','Image input and generation usage across multimodal models.',`<div class="image-rank-grid">${[['Gemini 3.8 Flash','124M images','#dfeaff'],['GPT-5.6 Sol','98M images','#d7f5e7'],['Claude Opus 5','76M images','#f4dfcf'],['Muse Image','51M images','#eadfff']].map((x,i)=>`<article><div style="background:${x[2]}"><i>${['G','O','A','M'][i]}</i><span>${icon('image')}</span></div><strong>${x[0]}</strong><small>${x[1]}</small></article>`).join('')}</div>`)}${rankingSection('top-apps','Top Apps','Public apps and agents opting into usage tracking.',`<div class="top-apps-list">${[['Hermes Agent','1.54T','Open-source agent with persistent memory'],['Claude Code','340B','Anthropic’s agentic coding tool'],['Cline','320B','Autonomous coding inside your IDE'],['Kilo Code','297B','Agentic coding for IDE and CLI'],['Pi','222B','The coding agent that is yours'],['OpenClaw','130B','Personal AI assistant']].map((x,i)=>`<article><b>${String(i+1).padStart(2,'0')}</b><i>${x[0][0]}</i><span><strong>${x[0]}</strong><small>${x[2]}</small></span><em>${x[1]}<small>tokens</small></em>${icon('arrow-up-right')}</article>`).join('')}</div>`,`<button class="secondary export-rank">Browse apps ${icon('arrow-right')}</button>`)}<div class="rankings-license">Rankings data is licensed under CC BY 4.0. Usage rankings measure adoption, not model quality.</div></main></div>${footer()}</div>`}

function oriInstall(){return state.oriOS==='Windows'?`irm https://openrouter.ai/labs/ori/install.ps1 | iex`:`curl -fsSL https://openrouter.ai/labs/ori/install.sh | bash`}
function oriRun(){return `ori ${state.oriHarness} --model ${state.oriModel}`}
function oriPage(){const current=harnesses.find(x=>x.id===state.oriHarness);return `<div class="page ori-page"><section class="ori-hero"><div class="container ori-hero-grid"><div><div class="ori-label"><span class="ori-mark"><i></i><i></i><i></i></span>OPENROUTER ORI</div><h1>Your agent.<br><span>Every model.</span></h1><p>Run Claude Code, Codex, OpenCode, Hermes, Pi and more on OpenRouter. Sign in once and get an optimized configuration for every harness.</p><div class="hero-actions"><button class="primary" data-scroll-ori="install">Install Ori ${icon('arrow-down')}</button><a class="secondary" href="#docs">Read the docs ${icon('arrow-up-right')}</a></div><div class="ori-trust"><span>${icon('key-round')} No API key to paste</span><span>${icon('shield-check')} Organization policies included</span></div></div><div class="ori-console" aria-label="Ori 命令行演示"><div class="terminal-chrome"><i></i><i></i><i></i><span>~/your-project</span></div><div class="terminal-body"><p><b>$</b> ori ${current.id} <span>--model ${state.oriModel}</span></p><p class="terminal-muted">✓ Signed in as developer@team</p><p class="terminal-muted">✓ Loaded 500+ models from OpenRouter</p><p class="terminal-muted">✓ Applied optimized ${current.name} configuration</p><div class="terminal-ready"><i></i><strong>${current.name} is ready</strong><small>${current.note}</small></div><p class="terminal-cursor"><b>›</b> Build a production-ready API… <i></i></p></div></div></div></section><section class="harness-band"><div class="container"><span class="band-label">WORKS WITH THE TOOLS YOU ALREADY USE</span><div class="harness-logos">${harnesses.map(x=>`<span><i style="background:${x.color}">${x.mark}</i>${x.name}</span>`).join('')}</div></div></section><section class="ori-builder section"><div class="container"><div class="section-head"><div><p class="eyebrow">Try the command</p><h2>Bring your own agent</h2><p>Pick a harness and model. Ori handles authentication and generates the right configuration.</p></div><span class="step-counter">01 / 03</span></div><div class="ori-builder-grid"><div class="harness-picker"><span class="picker-label">1. SELECT YOUR HARNESS</span>${harnesses.map(x=>`<button class="${state.oriHarness===x.id?'active':''}" data-harness="${x.id}"><i style="background:${x.color}">${x.mark}</i><span><strong>${x.name}</strong><small>${x.note}</small></span>${icon('check')}</button>`).join('')}</div><div class="command-builder"><label><span>2. CHOOSE ANY MODEL</span><select id="oriModel"><option value="openrouter/auto" ${state.oriModel==='openrouter/auto'?'selected':''}>Auto Router · recommended</option><option value="anthropic/claude-opus-5" ${state.oriModel==='anthropic/claude-opus-5'?'selected':''}>Anthropic · Claude Opus 5</option><option value="openai/gpt-5.6-sol" ${state.oriModel==='openai/gpt-5.6-sol'?'selected':''}>OpenAI · GPT-5.6 Sol</option><option value="google/gemini-3.8-flash" ${state.oriModel==='google/gemini-3.8-flash'?'selected':''}>Google · Gemini 3.8 Flash</option><option value="deepseek/deepseek-v4" ${state.oriModel==='deepseek/deepseek-v4'?'selected':''}>DeepSeek · V4 Flash</option></select>${icon('chevron-down')}</label><span class="picker-label">3. RUN FROM YOUR PROJECT</span><div class="built-command"><code><b>$</b> <span id="oriCommand">${oriRun()}</span></code><button class="copy-btn" id="copyOriRun" aria-label="复制运行命令">${icon('copy')}</button></div><div class="command-result"><span>${icon('check-circle-2')} Ori will:</span><ul><li>Open secure OAuth sign-in</li><li>Pass through your usual agent flags</li><li>Apply the best settings for your selected model</li></ul></div></div></div></div></section><section class="ori-benefits"><div class="container"><div class="section-head"><div><p class="eyebrow">One thin layer</p><h2>Less configuration.<br>More agent.</h2></div></div><div class="ori-benefit-grid"><article><span>01</span>${icon('fingerprint')}<h3>Sign in, don't manage keys</h3><p>OAuth PKCE connects your OpenRouter account. Models, credits, and organization settings come with you.</p></article><article><span>02</span>${icon('sliders-horizontal')}<h3>Optimized per harness</h3><p>Ori detects your model and tunes tool search, system prompts, endpoints, and defaults automatically.</p></article><article><span>03</span>${icon('shuffle')}<h3>Any model, one flag</h3><p>Use any model in your catalog with <code>--model</code>, while keeping every normal harness flag.</p></article><article><span>04</span>${icon('landmark')}<h3>One bill, one policy</h3><p>Usage appears beside all your other traffic. Guardrails and workspace budgets apply everywhere.</p></article></div></div></section><section class="ori-compare section"><div class="container"><div class="section-head"><div><p class="eyebrow">Under the hood</p><h2>One command replaces the wall.</h2></div></div><div class="compare-grid"><div class="config-wall"><div class="compare-label"><span>WITHOUT ORI</span><em>11 variables</em></div><pre>ANTHROPIC_BASE_URL=https://openrouter.ai/api
ANTHROPIC_AUTH_TOKEN=&lt;api-key&gt;
OPENROUTER_API_KEY=&lt;api-key&gt;
CLAUDE_CODE_SKIP_FAST_MODE_ORG_CHECK=1
CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY=1
ENABLE_TOOL_SEARCH=true
CLAUDE_CODE_SIMPLE_SYSTEM_PROMPT=1
ANTHROPIC_DEFAULT_HAIKU_MODEL=~anthropic/...
ANTHROPIC_DEFAULT_SONNET_MODEL=~anthropic/...
ANTHROPIC_DEFAULT_OPUS_MODEL=~anthropic/...</pre></div><div class="config-simple"><div class="compare-label"><span>WITH ORI</span><em>1 command</em></div><code><b>$</b> ori claude</code><div><i>${icon('check')}</i><span><strong>Configuration detected</strong><small>Applied automatically for your model</small></span></div></div></div></div></section><section class="ori-install section" id="ori-install"><div class="container install-inner"><div><p class="eyebrow">Get started</p><h2>From zero to agent<br>in under a minute.</h2><p>Install the CLI, sign in with OpenRouter, then run the agent you already know.</p></div><div class="install-console"><div class="install-tabs">${['macOS','Linux','Windows'].map(x=>`<button class="${state.oriOS===x?'active':''}" data-os="${x}">${x}</button>`).join('')}</div><div class="install-line"><code><b>$</b> <span id="oriInstallCommand">${oriInstall()}</span></code><button class="copy-btn" id="copyOriInstall">${icon('copy')}</button></div><div class="install-steps"><p><b>01</b><span><strong>Install Ori</strong><small>One shell command</small></span></p><p><b>02</b><span><strong>Run <code>ori login</code></strong><small>Secure browser sign-in</small></span></p><p><b>03</b><span><strong>Run your harness</strong><small><code>${oriRun()}</code></small></span></p></div></div></div></section><section class="container ori-faq section"><div class="section-head"><div><p class="eyebrow">Questions</p><h2>Ori, explained.</h2></div></div>${faqItem('Do I need an OpenRouter API key?','No. Ori uses OAuth PKCE through your OpenRouter login, so there is no key to create, copy, or paste.',true)}${faqItem('Do I need to change my agent workflow?','No. Keep the same agent, commands, and flags. Ori passes your usual flags through unchanged.')}${faqItem('Which agents are supported?','Claude Code, Codex, Grok Build, Hermes, OpenCode, Pi, Prime Agent, and DeepSeek Harness are represented in this prototype.')}${faqItem('Does Ori add another bill?','No. Ori traffic is part of normal OpenRouter billing and activity reporting.')}</section>${footer()}</div>`}

function bindOri(){document.querySelectorAll('[data-harness]').forEach(b=>b.onclick=()=>{state.oriHarness=b.dataset.harness;route()});document.querySelector('#oriModel').onchange=e=>{state.oriModel=e.target.value;route()};document.querySelectorAll('[data-os]').forEach(b=>b.onclick=()=>{state.oriOS=b.dataset.os;route()});document.querySelector('#copyOriRun').onclick=()=>{navigator.clipboard?.writeText(oriRun());toast('Run command copied')};document.querySelector('#copyOriInstall').onclick=()=>{navigator.clipboard?.writeText(oriInstall());toast('Install command copied')};document.querySelector('[data-scroll-ori]').onclick=()=>document.querySelector('#ori-install').scrollIntoView({behavior:'smooth'});document.querySelectorAll('.ori-page .faq-item button').forEach(b=>b.onclick=()=>{const item=b.closest('.faq-item'),open=item.classList.toggle('open');b.setAttribute('aria-expanded',open)})}

const snippets={curl:`<span class="fn">curl</span> https://openrouter.ai/api/v1/chat/completions \\\n+  -H <span class="str">"Authorization: Bearer $OPENROUTER_API_KEY"</span> \\\n+  -H <span class="str">"Content-Type: application/json"</span> \\\n+  -d <span class="str">'{\n    "model": "openai/gpt-5.6-sol",\n    "messages": [{"role":"user","content":"Hello"}]\n  }'</span>`,typescript:`<span class="kw">import</span> { OpenRouter } <span class="kw">from</span> <span class="str">'@openrouter/sdk'</span>;\n\n<span class="kw">const</span> client = <span class="kw">new</span> <span class="fn">OpenRouter</span>({\n  apiKey: process.env.OPENROUTER_API_KEY\n});\n\n<span class="kw">const</span> result = <span class="kw">await</span> client.chat.<span class="fn">send</span>({\n  model: <span class="str">'openai/gpt-5.6-sol'</span>,\n  messages: [{ role: <span class="str">'user'</span>, content: <span class="str">'Hello'</span> }]\n});`,python:`<span class="kw">from</span> openai <span class="kw">import</span> OpenAI\n\nclient = OpenAI(\n  base_url=<span class="str">"https://openrouter.ai/api/v1"</span>,\n  api_key=os.environ[<span class="str">"OPENROUTER_API_KEY"</span>]\n)\n\ncompletion = client.chat.completions.<span class="fn">create</span>(\n  model=<span class="str">"openai/gpt-5.6-sol"</span>,\n  messages=[{<span class="str">"role"</span>: <span class="str">"user"</span>, <span class="str">"content"</span>: <span class="str">"Hello"</span>}]\n)`};
function docsPage(){return `<div class="docs-page"><aside class="docs-sidebar"><label class="docs-search">${icon('search')}<input placeholder="Search docs…"></label><div class="docs-group"><h3>Getting started</h3><a class="active">Quickstart</a><a>Principles</a><a>Models</a><a>Authentication</a></div><div class="docs-group"><h3>Core concepts</h3><a>Model routing</a><a>Provider routing</a><a>Fallbacks</a><a>Latency & performance</a></div><div class="docs-group"><h3>Features</h3><a>Structured outputs</a><a>Tool calling</a><a>Prompt transforms</a></div></aside><article class="doc-content"><p class="eyebrow">Getting started</p><h1>Quickstart</h1><p class="doc-lead">Start routing requests to hundreds of AI models with a single API. OpenRouter is compatible with the OpenAI chat completion format.</p><div class="callout">${icon('info')}<span>You need an API key before making your first request. Keys can be scoped and revoked at any time.</span></div><h2 id="first-request">Make your first request</h2><p>Choose your preferred language below. The same normalized request works across every compatible model.</p>${codeBox()}<h2 id="routing">Model routing</h2><p>Change only the model identifier to route the same request to another provider. You can also pass a list of fallback models to increase availability.</p><h2 id="next">Next steps</h2><p>Explore provider routing, structured outputs, tool calls, and usage accounting in the guides.</p></article><aside class="toc"><h3>On this page</h3><a href="#docs/first-request">Make your first request</a><a href="#docs/routing">Model routing</a><a href="#docs/next">Next steps</a></aside></div>`}
function codeBox(lang='curl'){return `<div class="code-box"><div class="code-head"><div class="code-tabs">${['curl','typescript','python'].map(x=>`<button class="${x===lang?'active':''}" data-code="${x}">${x==='typescript'?'TypeScript':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><button class="copy-btn" title="复制代码" aria-label="复制代码">${icon('copy')}</button></div><pre><code id="codeContent">${snippets[lang]}</code></pre></div>`}

function route(){const parts=(location.hash.slice(1)||'home').split('/'),page=parts[0],section=parts[1];document.querySelectorAll('.desktop-nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#${page}`||(page==='model'&&a.getAttribute('href')==='#models')));document.querySelector('#mobileNav').classList.remove('open');if(page==='models')app.innerHTML=modelsPage();else if(page==='providers')app.innerHTML=providersPage();else if(page==='model'){const m=models.find(x=>x.id===parts[1])||models[0];app.innerHTML=modelDetailPageV2(m,parts[2]||'providers')}else if(page==='benchmarks')app.innerHTML=benchmarkPage();else if(page==='rankings')app.innerHTML=rankingsPageV2(parts[1]||'top-models');else if(page==='ori')app.innerHTML=oriPage();else if(page==='docs')app.innerHTML=docsPage();else app.innerHTML=home();bindPage(page);lucide.createIcons();const target=page==='model'&&parts[2]?parts[2]:page==='rankings'&&section?section:page==='docs'?section:null;if(target)requestAnimationFrame(()=>document.getElementById(target)?.scrollIntoView({behavior:'smooth'}));else scrollTo(0,0)}
function bindPage(page){if(page==='models'){renderModels();document.querySelector('#modelSearch').addEventListener('input',e=>{state.search=e.target.value;renderModels()});document.querySelector('#modelSort').addEventListener('change',e=>{state.sort=e.target.value;renderModels()});document.querySelectorAll('.check input').forEach(x=>x.addEventListener('change',e=>{e.target.checked?state.filters.add(e.target.value):state.filters.delete(e.target.value);renderModels()}));document.querySelector('#resetFilters').onclick=()=>{state.filters.clear();state.search='';route()};document.querySelector('#mobileFilter').onclick=()=>document.querySelector('#filterSide').classList.toggle('open');document.querySelectorAll('[data-collection]').forEach(x=>x.onclick=()=>{state.filters.clear();state.search='';if(x.dataset.collection==='reasoning')state.filters.add('Reasoning');if(x.dataset.collection==='multimodal')state.filters.add('Image');if(x.dataset.collection==='free')state.filters.add('Free');route()})}if(page==='providers'){renderProviders();document.querySelector('#providerSearch').oninput=e=>{state.providerSearch=e.target.value;renderProviders()};document.querySelectorAll('[data-provider-filter]').forEach(b=>b.onclick=()=>{state.providerFilters.has(b.dataset.providerFilter)?state.providerFilters.delete(b.dataset.providerFilter):state.providerFilters.add(b.dataset.providerFilter);route()});document.querySelector('#compareProviders').onclick=openProviderCompare}
if(page==='benchmarks'){renderBenchmarks();document.querySelector('#benchTabs').onclick=e=>{if(!e.target.dataset.bench)return;state.bench=e.target.dataset.bench;document.querySelectorAll('#benchTabs button').forEach(x=>x.classList.toggle('active',x===e.target));renderBenchmarks()}}
if(page==='rankings'){renderChart();document.querySelector('#periodTabs').onclick=e=>{if(!e.target.dataset.period)return;state.period=e.target.dataset.period;route()};document.querySelector('#metricTabs').onclick=e=>{if(!e.target.dataset.metric)return;state.metric=e.target.dataset.metric;route()};document.querySelectorAll('[data-rank-task]').forEach(b=>b.onclick=()=>{state.rankTask=b.dataset.rankTask;route()})}
if(page==='docs')document.querySelector('.doc-content').addEventListener('click',docClick);if(page==='ori')bindOri();if(page==='model'){document.querySelectorAll('.faq-item button').forEach(b=>b.onclick=()=>{const item=b.closest('.faq-item'),open=item.classList.toggle('open');b.setAttribute('aria-expanded',open)});const range=document.querySelector('#costRange');if(range)range.oninput=e=>{const m=models.find(x=>x.id===(location.hash.split('/')[1]))||models[0],v=Number(e.target.value);document.querySelector('#tokenAmount').textContent=`${v}M tokens`;document.querySelector('#costEstimate').textContent=`$${(m.input*v).toFixed(2)}`}}}
function docClick(e){const lang=e.target.dataset.code;if(lang){e.target.closest('.code-box').outerHTML=codeBox(lang);lucide.createIcons();return}if(e.target.closest('.copy-btn')){navigator.clipboard?.writeText(document.querySelector('#codeContent').textContent);toast('Code copied to clipboard')}}
function openDrawer(id){const m=models.find(x=>x.id===id);if(!m)return;document.querySelector('#modelDrawer').innerHTML=`<button class="icon-btn drawer-close" data-close-drawer aria-label="关闭详情">${icon('x')}</button><div class="drawer-brand">${logo(m)}<div><h2>${m.name}</h2><p>${m.vendor} / ${m.id}</p></div></div><p class="drawer-copy">${m.desc}</p><div class="model-tags">${m.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div><div class="drawer-stats"><div class="drawer-stat"><span>CONTEXT</span><strong>${m.context}</strong></div><div class="drawer-stat"><span>INPUT</span><strong>$${m.input}/M</strong></div><div class="drawer-stat"><span>OUTPUT</span><strong>$${m.output}/M</strong></div></div><div class="drawer-actions"><button class="primary" data-toast="模型已添加到 Chat">Try in Chat ${icon('arrow-right')}</button><button class="secondary" data-toast="模型 ID 已复制">${icon('copy')} Copy model ID</button></div>`;const shell=document.querySelector('#drawerShell');shell.classList.add('open');shell.setAttribute('aria-hidden','false');lucide.createIcons()}
function closeDrawer(){document.querySelector('#drawerShell').classList.remove('open');document.querySelector('#drawerShell').setAttribute('aria-hidden','true')}
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.querySelector('#toastStack').append(el);setTimeout(()=>el.remove(),2600)}
document.addEventListener('click',e=>{const noRoute=e.target.closest('[data-no-route]');if(noRoute)e.preventDefault();const detail=e.target.closest('[data-detail]');if(detail)location.hash=`model/${detail.dataset.detail}/providers`;const model=e.target.closest('[data-model]');if(model)openDrawer(model.dataset.model);const copy=e.target.closest('[data-copy]');if(copy){navigator.clipboard?.writeText(copy.dataset.copy);toast('Model ID copied')}if(e.target.closest('[data-close-drawer]'))closeDrawer();const t=e.target.closest('[data-toast]');if(t)toast(t.dataset.toast)});
document.querySelector('#themeButton').onclick=()=>{document.documentElement.classList.toggle('dark');document.querySelector('#themeButton').innerHTML=icon(document.documentElement.classList.contains('dark')?'moon':'sun');lucide.createIcons()};
document.querySelector('#menuButton').onclick=()=>document.querySelector('#mobileNav').classList.toggle('open');
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(e.key==='Enter'&&document.activeElement?.dataset.detail)location.hash=`model/${document.activeElement.dataset.detail}/providers`;if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();(document.querySelector('#modelSearch')||document.querySelector('#providerSearch'))?.focus()}});
window.addEventListener('hashchange',route);route();
